namespace RelayPulse.Core.Statistics;

/// <summary>
/// Exact Poisson tail tests against the baseline λ. Asymmetric on purpose: a drop is the costlier
/// miss for a customer, so the low tail is 5× more sensitive than the high tail.
/// </summary>
public static class Significance
{
    public const double AlphaLow = 0.025;
    public const double AlphaHigh = 0.005;

    /// <summary>
    /// Volume gate. Just above ln(1/α_low) = 3.689, the λ at which an empty week first becomes
    /// detectable as Below; under it the test can only ever flag large spikes.
    /// </summary>
    public const double MinLambda = 3.7;

    /// <summary>The integer counts that <see cref="Assess"/> would call Normal (ignoring the gate).</summary>
    public static CountBand BandFor(double lambda)
    {
        // Lower(n) rises with n, Upper(n) falls: both edges are binary searches.
        // lo: smallest n with P(X ≤ n) ≥ α_low. P(X ≤ ⌈λ⌉) is about ½, so the search stays below ⌈λ⌉.
        var lo = FirstWhere(0, (int)Math.Ceiling(lambda), n => PoissonTail.Lower(n, lambda) >= AlphaLow);

        // hi: one below the smallest n with P(X ≥ n) < α_high. λ + 10√λ + 20 is far past that.
        var ceiling = (int)Math.Ceiling(lambda + 10 * Math.Sqrt(lambda) + 20);
        var hi = FirstWhere(1, ceiling, n => PoissonTail.Upper(n, lambda) < AlphaHigh) - 1;

        return new CountBand(lo, hi);
    }

    public static Assessment Assess(int count, double? lambda)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(count);
        if (lambda is not { } l)
        {
            return new Assessment(Verdict.InsufficientHistory, double.PositiveInfinity);
        }

        var pLow = PoissonTail.Lower(count, l);
        var pHigh = PoissonTail.Upper(count, l);
        var band = BandFor(l);

        if (l < MinLambda)
        {
            return new Assessment(Verdict.NotEnoughVolume, double.PositiveInfinity, l, band, pLow, pHigh);
        }

        var verdict = pLow < AlphaLow ? Verdict.Below
            : pHigh < AlphaHigh ? Verdict.Above
            : Verdict.Normal;
        var rankKey = Math.Min(pLow / AlphaLow, pHigh / AlphaHigh);

        return new Assessment(verdict, rankKey, l, band, pLow, pHigh);
    }

    // Smallest n in [from, to] satisfying a monotone predicate (false…false true…true); to if none.
    private static int FirstWhere(int from, int to, Func<int, bool> predicate)
    {
        while (from < to)
        {
            var mid = from + (to - from) / 2;
            if (predicate(mid))
            {
                to = mid;
            }
            else
            {
                from = mid + 1;
            }
        }

        return from;
    }
}
