        var rows = Steady("Site A", 10)
            .Concat(Calls("Site A", new DateOnly(2026, 1, 26), 500)) // partial edge bucket
            .Concat(Calls("Site A", Weeks[^1].AddDays(7), 500))       // after the target
            .ToList();

        var report = PulseBuilder.Build(Weeks, Target, rows);

        Assert.Equal(10, report.Account.Count);
        Assert.Equal(10.0, report.Account.Assessment.Lambda!.Value, 10);
    }

    [Fact]
    public void Build_AccountRow_UsesAccountGrainRows()
    {
        var rows = Steady("Site A", 10).Concat(Steady("Site B", 30)).ToList();

        var report = PulseBuilder.Build(Weeks, Target, rows);

        Assert.Null(report.Account.Location);
        Assert.Equal(40, report.Account.Count);
        Assert.Equal(40.0, report.Account.Assessment.Lambda!.Value, 10);
    }

    [Fact]
    public void Build_Locations_FlaggedFirstThenByRankKeyThenName()
    {
        var rows = Steady("Site C", 20)                                 // normal
            .Concat(Steady("Site B", 20, weeks: 13))                    // 0 in target → below
            .Concat(Steady("Site A", 20))                               // normal, ties with C
            .Concat(Steady("Site D", 1))                                // λ=1 → not enough volume
            .Concat(Steady("Site E", 20, weeks: 13)).Concat(Calls("Site E", Target, 60)) // above
            .ToList();

        var report = PulseBuilder.Build(Weeks, Target, rows);

        // E: P(X≥60 | 20)/α_high ≈ 1e-10 beats B: P(X≤0 | 20)/α_low ≈ 8e-8. A and C tie → by name.
        Assert.Equal(new[] { "Site E", "Site B", "Site A", "Site C", "Site D" }, report.Locations.Select(l => l.Location));
        Assert.All(report.Locations.Take(2), l => Assert.True(l.Assessment.RankKey < 1));
        Assert.Equal(Verdict.NotEnoughVolume, report.Locations[^1].Assessment.Verdict);
    }

    [Fact]
    public void Build_NullOutcome_IsCountedAsUnspecified()
    {
        var rows = Steady("Site A", 10)
            .Concat(Calls("Site A", Target, 3, outcome: null))
            .Append(new WeeklyCount(Target, "Site A", "lead_created", "converted", 2))
            .Append(new WeeklyCount(Target, null, "lead_created", "converted", 2))
            .ToList();

        var report = PulseBuilder.Build(Weeks, Target, rows);

        var a = report.Locations[0];
        Assert.Equal(15, a.Count);
        var calls = Assert.Single(a.ByType, t => t.EventType == "call_received");
        Assert.Equal(13, calls.Count);
        Assert.Equal(10, calls.Outcomes["connected"]);
        Assert.Equal(3, calls.Outcomes[PulseBuilder.UnspecifiedOutcome]);
        Assert.Equal(2, Assert.Single(a.ByType, t => t.EventType == "lead_created").Count);
        Assert.Equal(15, report.Account.ByType.Sum(t => t.Count));
    }

    [Fact]
    public void Build_NoRows_IsEmptyWithInsufficientHistoryNotZeroVolume()
    {
        var report = PulseBuilder.Build(Weeks, Target, []);

        Assert.False(report.HasEvents);
        Assert.Empty(report.Locations);
        Assert.Equal(0, report.Account.Count);
        Assert.Equal(Verdict.InsufficientHistory, report.Account.Assessment.Verdict);
    }

    [Fact]
    public void Build_TargetNotAmongCompleteWeeks_Throws()
    {
        Assert.Throws<ArgumentException>(() => PulseBuilder.Build(Weeks, new DateOnly(2026, 1, 26), []));
    }
}

using RelayPulse.Core.Statistics;

namespace RelayPulse.Core.Pulse;

/// <summary>
/// Turns aggregation rows into judged series for one account-week. Pure: no clock, no I/O.
/// </summary>
public static class PulseBuilder
{
    public const string UnspecifiedOutcome = "unspecified";

    /// <param name="completeWeeks">
    /// The account timezone's complete week Mondays, ascending. These define the zero-fill: every
    /// series gets a count for each of them, and nothing outside them is ever read.
    /// </param>
    /// <param name="week">The week being judged; must be one of <paramref name="completeWeeks"/>.</param>
    /// <param name="rows">Both grains from the aggregation query; rows outside the window are ignored.</param>
    public static PulseReport Build(IReadOnlyList<DateOnly> completeWeeks, DateOnly week, IReadOnlyList<WeeklyCount> rows)
    {
        ArgumentNullException.ThrowIfNull(completeWeeks);
        ArgumentNullException.ThrowIfNull(rows);

        var targetIndex = IndexOf(completeWeeks, week);
        if (targetIndex < 0)
        {
            throw new ArgumentException($"{week:yyyy-MM-dd} is not a complete week.", nameof(week));
        }

        // Up to and including the target; weeks after it and partial weeks never enter.
        var inWindow = completeWeeks.Take(targetIndex + 1).ToHashSet();
        var relevant = rows.Where(r => inWindow.Contains(r.WeekStart)).ToList();
        var prior = completeWeeks.Take(targetIndex).ToList();

        if (relevant.Count == 0)
        {
            // No events at all is no history, not a zero-volume history.
            var empty = new SeriesPulse(null, 0, prior.Count, Significance.Assess(0, null), []);
            return new PulseReport(false, empty, []);
        }

        var account = Judge(null, relevant.Where(r => r.Location is null).ToList(), prior, week);
        var locations = relevant
            .Where(r => r.Location is not null)
            .GroupBy(r => r.Location!, StringComparer.Ordinal)
            .Select(g => Judge(g.Key, g.ToList(), prior, week))
            .OrderBy(s => s.Assessment.RankKey)
            .ThenBy(s => s.Location, StringComparer.Ordinal)
            .ToList();

        return new PulseReport(true, account, locations);
    }

    private static SeriesPulse Judge(string? location, List<WeeklyCount> rows, List<DateOnly> prior, DateOnly week)
    {
        var perWeek = rows
            .GroupBy(r => r.WeekStart)
            .ToDictionary(g => g.Key, g => g.Sum(r => r.Events));

        var history = prior.Select(w => perWeek.GetValueOrDefault(w)).ToList();
        var count = perWeek.GetValueOrDefault(week);
        var byType = rows
            .Where(r => r.WeekStart == week)
            .GroupBy(r => r.EventType, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .Select(g => new TypeSplit(
                g.Key,
                g.Sum(r => r.Events),
                g.GroupBy(r => r.Outcome ?? UnspecifiedOutcome, StringComparer.Ordinal)
                    .OrderBy(o => o.Key, StringComparer.Ordinal)
                    .ToDictionary(o => o.Key, o => o.Sum(r => r.Events), StringComparer.Ordinal)))
            .ToList();

        return new SeriesPulse(
            location,
            count,
            Math.Min(history.Count, Baseline.Window),
            Significance.Assess(count, Baseline.Lambda(history)),
            byType);
    }

    private static int IndexOf(IReadOnlyList<DateOnly> weeks, DateOnly week)
    {
        for (var i = 0; i < weeks.Count; i++)
        {
            if (weeks[i] == week)
            {
                return i;
            }
        }

        return -1;
    }
}

using System.Globalization;
using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.EntityFrameworkCore;
using RelayPulse.Api.Data;
using RelayPulse.Core.Pulse;
using RelayPulse.Core.Statistics;

namespace RelayPulse.Api.Pulse;

public static class PulseEndpoints
{
    public const string InvalidWeek = "pulse.invalid_week";
    public const string AccountNotFound = "pulse.account_not_found";

    public static IEndpointRouteBuilder MapPulse(this IEndpointRouteBuilder app)
    {
        app.MapGet("/api/accounts/{id:int}/pulse", GetPulseAsync);
        return app;
    }

    private static async Task<Results<Ok<PulseResponse>, ProblemHttpResult>> GetPulseAsync(
        int id,
        string? week,
        RelayDbContext db,
        PulseQuery query,
        ILoggerFactory loggerFactory,
        CancellationToken cancellationToken)
    {
        var logger = loggerFactory.CreateLogger(typeof(PulseEndpoints).FullName!);
        DateOnly? requested = null;
        if (week is not null)
        {
            if (!DateOnly.TryParseExact(week, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var parsed))
            {
                return Problem(400, InvalidWeek, $"'{week}' is not a date in YYYY-MM-DD form.");
            }

            requested = parsed;
        }

        var account = await db.Accounts.AsNoTracking().SingleOrDefaultAsync(a => a.Id == id, cancellationToken);
        if (account is null)
        {
            return Problem(404, AccountNotFound, $"No account with id {id}.");
        }

        // Complete weeks come from week_buckets, which is built from the global MIN/MAX(occurred_at):
        // the default is the last complete week of the data, never of the wall clock.
        var completeWeeks = await db.WeekBuckets.AsNoTracking()
            .Where(b => b.Timezone == account.Timezone && b.IsComplete)
            .OrderBy(b => b.WeekStartLocal)
            .Select(b => b.WeekStartLocal)
            .ToListAsync(cancellationToken);

        if (completeWeeks.Count == 0)
        {
            return Problem(400, InvalidWeek, "There are no complete weeks of data yet.");
        }

        var target = requested ?? completeWeeks[^1];
        var index = completeWeeks.BinarySearch(target);
        if (index < 0)
        {
            return Problem(400, InvalidWeek,
                $"{target:yyyy-MM-dd} is not the Monday of a complete week; choose a Monday from " +
                $"{completeWeeks[0]:yyyy-MM-dd} to {completeWeeks[^1]:yyyy-MM-dd}.");
        }

        // Only the baseline window and the target week are needed.
        var from = completeWeeks[Math.Max(0, index - Baseline.Window)];
        var rows = await query.RunAsync(id, from, target, cancellationToken);
        var report = PulseBuilder.Build(completeWeeks, target, rows);

        logger.LogInformation("Pulse: served {AccountId} week {Week}", id, target);

        return TypedResults.Ok(new PulseResponse(
            account.Id,
            account.Name,
            account.Timezone,
            new PulsePeriod(
                target,
                target.AddDays(6),
                requested is null,
                completeWeeks[0],
                completeWeeks[^1],
                index > 0 ? completeWeeks[index - 1] : null,
                index < completeWeeks.Count - 1 ? completeWeeks[index + 1] : null),
            report.HasEvents ? "ok" : "empty",
            PulseRow.From(report.Account),
            report.Locations.Select(PulseRow.From).ToList()));
    }

    private static ProblemHttpResult Problem(int status, string code, string detail) =>
        TypedResults.Problem(statusCode: status, title: code, detail: detail);
}

