using DotNet.Testcontainers.Builders;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using RelayPulse.Api.Data;
using RelayPulse.Api.Data.Seeding;
using Testcontainers.MsSql;

namespace RelayPulse.Tests.Integration;

/// <summary>
/// A throwaway SQL Server with db/seed.sql loaded through the real seed command path (migrations,
/// dedupe view, week_buckets), and the API pointed at it. When Docker is absent the fixture
/// records why and every test skips with that message, so `dotnet test` stays green without it.
/// </summary>
public sealed class SeededApiFixture : IAsyncLifetime
{
    private const string Image = "mcr.microsoft.com/mssql/server:2022-latest";

    private MsSqlContainer? _sql;

    public WebApplicationFactory<Program>? Factory { get; private set; }

    public string? SkipReason { get; private set; }

    public async ValueTask InitializeAsync()
    {
        var cancellationToken = TestContext.Current.CancellationToken;
        try
        {
            _sql = new MsSqlBuilder(Image).Build();
            await _sql.StartAsync(cancellationToken);
        }
        catch (DockerUnavailableException ex)
        {
            SkipReason = $"Integration tests need Docker, which is not available: {ex.Message}";
            return;
        }

        // Anything failing past this point is a real failure, not a skip.
        var connectionString = new SqlConnectionStringBuilder(_sql.GetConnectionString())
        {
            InitialCatalog = "RelayPulse",
        }.ConnectionString;

        Factory = new WebApplicationFactory<Program>()
            .WithWebHostBuilder(b => b.UseSetting("ConnectionStrings:Relay", connectionString));

        await using var scope = Factory.Services.CreateAsyncScope();

        // Guard: if the override ever stops reaching Program, the tests would silently run against
        // the developer's compose database instead of this container.
        var db = scope.ServiceProvider.GetRequiredService<RelayDbContext>();
        var actual = new SqlConnectionStringBuilder(db.Database.GetConnectionString());
        if (actual.DataSource != new SqlConnectionStringBuilder(connectionString).DataSource)
        {
            throw new InvalidOperationException($"API is not using the test container (got {actual.DataSource}).");
        }

        await scope.ServiceProvider.GetRequiredService<SeedImporter>()
            .RunAsync(SeedPath.Resolve(null), cancellationToken);
    }

    public async ValueTask DisposeAsync()
    {
        if (Factory is not null)
        {
            await Factory.DisposeAsync();
        }

        if (_sql is not null)
        {
            await _sql.DisposeAsync();
        }
    }
}

