using System.Net;
using System.Text.Json;

namespace RelayPulse.Tests.Integration;

/// <summary>
/// /pulse end to end: real SQL Server, real seed, assertions on the wire JSON. Every golden comes
/// from tools/profile_seed.py --dedupe or tools/pulse_oracle.py, never from the C#.
/// </summary>
public sealed class PulseEndpointTests(SeededApiFixture fixture) : IClassFixture<SeededApiFixture>
{
    private async Task<(HttpStatusCode Status, JsonElement Body)> GetAsync(string path)
    {
        Assert.SkipWhen(fixture.SkipReason is not null, fixture.SkipReason ?? "");
        using var client = fixture.Factory!.CreateClient();
        using var response = await client.GetAsync(path, TestContext.Current.CancellationToken);
        var json = await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken);
        return (response.StatusCode, JsonDocument.Parse(json).RootElement.Clone());
    }

    private static Dictionary<string, JsonElement> ByLocation(JsonElement body) =>
        body.GetProperty("locations").EnumerateArray().ToDictionary(l => l.GetProperty("location").GetString()!);

    [Theory]
    [InlineData(1, 53)]
    [InlineData(6, 87)]
    [InlineData(8, 7)]
    [InlineData(18, 20)]
    [InlineData(19, 13)]
    public async Task GetPulse_NoWeek_ServesLastCompleteWeekWithGoldenTotal(int accountId, int total)
    {
        var (status, body) = await GetAsync($"/api/accounts/{accountId}/pulse");

        Assert.Equal(HttpStatusCode.OK, status);
        var period = body.GetProperty("period");
        Assert.Equal("2026-07-20", period.GetProperty("weekStart").GetString());
        Assert.Equal("2026-07-26", period.GetProperty("weekEnd").GetString());
        Assert.True(period.GetProperty("isDefault").GetBoolean());
        Assert.Equal(JsonValueKind.Null, period.GetProperty("nextWeek").ValueKind);
        Assert.Equal("ok", body.GetProperty("state").GetString());
        Assert.Equal(total, body.GetProperty("account").GetProperty("count").GetInt32());
    }

    [Fact]
    public async Task GetPulse_Account1DefaultWeek_LocationCountsMatchGoldens()
    {
        var (_, body) = await GetAsync("/api/accounts/1/pulse");

        var counts = ByLocation(body).ToDictionary(kv => kv.Key, kv => kv.Value.GetProperty("count").GetInt32());
        Assert.Equal(
            new Dictionary<string, int> { ["Site A"] = 9, ["Site B"] = 10, ["Site C"] = 9, ["Site D"] = 9, ["Site E"] = 9, ["Site F"] = 7 },
            counts);
    }

    [Fact]
    public async Task GetPulse_TypeAndOutcomeSplits_AddUpAndKeepNullOutcomes()
    {
        var (_, body) = await GetAsync("/api/accounts/1/pulse");

        foreach (var row in body.GetProperty("locations").EnumerateArray().Append(body.GetProperty("account")))
        {
            var types = row.GetProperty("byType").EnumerateArray().ToList();
            Assert.Equal(row.GetProperty("count").GetInt32(), types.Sum(t => t.GetProperty("count").GetInt32()));
            Assert.All(types, t => Assert.Equal(
                t.GetProperty("count").GetInt32(),
                t.GetProperty("outcomes").EnumerateObject().Sum(o => o.Value.GetInt32())));
        }

        // 3.2% of rows have a NULL outcome; at account grain some must surface, not vanish.
        var accountOutcomes = body.GetProperty("account").GetProperty("byType").EnumerateArray()
            .SelectMany(t => t.GetProperty("outcomes").EnumerateObject().Select(o => o.Name));
        Assert.Contains("unspecified", accountOutcomes);
    }

    [Theory]
    // Weekly totals over all 25 complete weeks, bucketed in the account's own timezone
    // (tools/pulse_oracle.py). UTC bucketing changes 1: 02-23, 03-02, 06-29, 07-06 and
    // 9: 06-29 … 07-20, so this fails if bucketing regresses to UTC.
    [InlineData(1, new[] { 43, 51, 40, 50, 51, 52, 36, 45, 61, 60, 37, 53, 56, 44, 58, 51, 46, 36, 47, 47, 39, 62, 42, 50, 53 })]
    [InlineData(9, new[] { 25, 21, 22, 23, 19, 20, 18, 21, 26, 24, 25, 31, 23, 12, 29, 26, 17, 18, 27, 20, 22, 16, 15, 17, 24 })]
    public async Task GetPulse_EveryCompleteWeek_MatchesAccountLocalGoldenSeries(int accountId, int[] series)
    {
        var week = new DateOnly(2026, 2, 2);
        var actual = new List<int>();
        for (var i = 0; i < series.Length; i++, week = week.AddDays(7))
        {
            var (status, body) = await GetAsync($"/api/accounts/{accountId}/pulse?week={week:yyyy-MM-dd}");
            Assert.Equal(HttpStatusCode.OK, status);
            actual.Add(body.GetProperty("account").GetProperty("count").GetInt32());
        }

        Assert.Equal(series, actual);
    }

    [Fact]
    public async Task GetPulse_Account6SpikeWeek_IsAboveAtBothGrains()
    {
        var (_, body) = await GetAsync("/api/accounts/6/pulse?week=2026-06-01");

        var account = body.GetProperty("account");
        Assert.Equal(880, account.GetProperty("count").GetInt32());
        Assert.Equal(72.1, account.GetProperty("lambda").GetDouble(), 9);
        Assert.Equal("above", account.GetProperty("verdict").GetString());
        var locations = body.GetProperty("locations").EnumerateArray().ToList();
        Assert.Equal(15, locations.Count);
        Assert.All(locations, l => Assert.Equal("above", l.GetProperty("verdict").GetString()));
        Assert.Equal(880, locations.Sum(l => l.GetProperty("count").GetInt32()));
    }

    [Fact]
    public async Task GetPulse_Account6WeekAfterSpike_BaselineTrimsTheSpike()
    {
        var (_, body) = await GetAsync("/api/accounts/6/pulse?week=2026-06-08");

        // 72.3 trimmed; a plain mean would be 138.0 and let 880 inflate the baseline.
        Assert.Equal(72.3, body.GetProperty("account").GetProperty("lambda").GetDouble(), 9);
    }

    [Fact]
    public async Task GetPulse_Account8DefaultWeek_IsNormalNotAMinus36PercentAlarm()
    {
        var (_, body) = await GetAsync("/api/accounts/8/pulse");

        var account = body.GetProperty("account");
        Assert.Equal(7, account.GetProperty("count").GetInt32());
        Assert.Equal(10.8, account.GetProperty("lambda").GetDouble(), 9);
        Assert.Equal(5, account.GetProperty("band").GetProperty("lo").GetInt32());
        Assert.Equal(20, account.GetProperty("band").GetProperty("hi").GetInt32());
        Assert.Equal("normal", account.GetProperty("verdict").GetString());
    }

    [Fact]
    public async Task GetPulse_ExactDuplicateRows_AreCountedOnce()
    {
        var (_, body) = await GetAsync("/api/accounts/6/pulse?week=2026-02-23");

        // Raw table: 3. Dedupe view: 2.
        Assert.Equal(2, ByLocation(body)["Site E"].GetProperty("count").GetInt32());
    }

    [Fact]
    public async Task GetPulse_AccountWithNoEvents_Returns200EmptyState()
    {
        var (status, body) = await GetAsync("/api/accounts/20/pulse");

        Assert.Equal(HttpStatusCode.OK, status);
        Assert.Equal("empty", body.GetProperty("state").GetString());
        Assert.Equal("2026-07-20", body.GetProperty("period").GetProperty("weekStart").GetString());
        var account = body.GetProperty("account");
        Assert.Equal(0, account.GetProperty("count").GetInt32());
        Assert.Equal("insufficient_history", account.GetProperty("verdict").GetString());
        Assert.Equal(JsonValueKind.Null, account.GetProperty("lambda").ValueKind);
        Assert.Empty(body.GetProperty("locations").EnumerateArray());
    }

    [Theory]
    [InlineData("2026-07-21")] // not a Monday
    [InlineData("2026-07-27")] // trailing partial week
    [InlineData("2026-01-26")] // leading partial week
    [InlineData("2026-08-03")] // after the data
    [InlineData("20260720")]
    [InlineData("junk")]
    public async Task GetPulse_InvalidWeek_Returns400ProblemWithCode(string week)
    {
        var (status, body) = await GetAsync($"/api/accounts/1/pulse?week={week}");

        Assert.Equal(HttpStatusCode.BadRequest, status);
        Assert.Equal("pulse.invalid_week", body.GetProperty("title").GetString());
    }

    [Fact]
    public async Task GetPulse_UnknownAccount_Returns404ProblemWithCode()
    {
        var (status, body) = await GetAsync("/api/accounts/999/pulse");

        Assert.Equal(HttpStatusCode.NotFound, status);
        Assert.Equal("pulse.account_not_found", body.GetProperty("title").GetString());
    }
}

